import { mountDashboard, icon } from './dashboard.mjs';
import { currencyFields, CURRENCIES, historyHTML } from './transfer-ui.mjs';
export function withdrawalHTML(){return '<div class="deposit-page"><div class="deposit-page-heading"><span class="deposit-heading-icon">'+icon('withdraw')+'</span><div><h1>Withdraw Crypto</h1><p>Withdraw your cryptocurrency to an external wallet</p></div></div><div class="deposit-columns"><section class="deposit-panel" aria-labelledby="withdraw-title"><h2 id="withdraw-title">'+icon('wallet')+' New Withdrawal</h2><div class="deposit-current-balance"><span>Available Balance</span><strong>Wallet not connected</strong></div><form id="withdraw-form" class="withdraw-form"><div id="withdraw-currency-fields">'+currencyFields('withdraw')+'</div><div class="transfer-field"><label for="withdraw-address">Withdrawal Address</label><input id="withdraw-address" placeholder="Enter BTC address" autocomplete="off" maxlength="180" aria-describedby="withdraw-preview-note"></div><div class="transfer-field"><label for="withdraw-amount">Amount (USD)</label><div class="deposit-amount-field"><span aria-hidden="true">$</span><input id="withdraw-amount" type="number" inputmode="decimal" value="100.00" min="50" step="0.01"></div><p class="transfer-caption">Minimum withdrawal: $50</p></div><dl class="withdraw-summary"><div><dt>Network Fee</dt><dd>Not configured</dd></div><div><dt>You will receive</dt><dd>—</dd></div></dl><button type="submit" class="deposit-continue">Submit Withdrawal '+icon('withdraw')+'</button><p id="withdraw-preview-note" class="deposit-availability">Preview only. Withdrawals and network fees are not connected.</p><p id="withdraw-feedback" class="transfer-placeholder-note" role="status" hidden></p></form></section>'+historyHTML('withdraw')+'</div></div>';}
export function mountWithdrawal(root,options={}){mountDashboard(root,{...options,view:'withdraw',mainHTML:withdrawalHTML()});let currency='BTC';function bindCurrency(){root.querySelector('#withdraw-currency').onchange=e=>{currency=e.target.value;root.querySelector('#withdraw-currency-fields').innerHTML=currencyFields('withdraw',currency,CURRENCIES[currency].networks[0]);root.querySelector('#withdraw-address').placeholder='Enter '+currency+' address';bindCurrency();root.querySelector('#withdraw-currency').focus();};}bindCurrency();root.querySelector('#withdraw-form').onsubmit=e=>{e.preventDefault();const msg=root.querySelector('#withdraw-feedback');msg.hidden=false;msg.textContent='Withdrawal preview only. Nothing was submitted and no funds were moved.';};window.scrollTo(0,0);}
